PLACEHOLDER = re.compile(r'no[_-]?pic|def[_-]?img|placeholder|logo|favicon|blank|default', re.I)

def _valid(u, hosts):
    p=urlsplit(u or '')
    return p.scheme=='https' and p.hostname in hosts and not p.username and not p.password

def _extract(page_url, session):
    r=session.get(page_url,timeout=22);r.raise_for_status()
    s=BeautifulSoup(r.text,'html.parser');host=urlsplit(page_url).hostname
    if host in ('ariela.today','www.ariela.today'):
        image=next((x.get('src') for x in s.select('main img[src]') if '/media/pages/' in x.get('src','')), None)
    elif 'levontin7.com' in host:
        im=s.select_one('.fat-event-thumb img[src]');image=im.get('src') if im else None
    else:
        im=s.select_one('meta[property="og:image"]');image=im.get('content') if im else None
    if not image:return None
    image=urljoin(page_url,image)
    if not _valid(image, ALLOWED_IMAGES) or PLACEHOLDER.search(urlsplit(image).path):return None
    credit=[x for x in s.stripped_strings if re.search(r'צילום\s*:',x) and len(x)<220]
    label='חומר קידום: '+('בית ליסין' if 'lessin.co.il' in host else 'לבונטין 7' if 'levontin7.com' in host else 'בית אריאלה ועיריית תל אביב-יפו')
    return {'original_image_url':image,'source_url':page_url,'credit':label+(' · '+credit[0] if credit else '')}

def enrich_events_images(events, asset_dir=None, asset_url_base=None):
    """Return records enriched once per exact source URL.
    asset_dir+asset_url_base download publication-ready jpg assets (recommended).
    Without them images remain official external URLs, with no guarantee of hotlinking.
    Caller owns publication/commit of generated assets with the refreshed feed.
    """
    by={e.get('source_url'):e for e in events if _valid(e.get('source_url'),ALLOWED_PAGES)}
    def one(pair):
        u,e=pair
        try:
            session=requests.Session();session.headers['User-Agent']='Mozilla/5.0 (ISNET official event publicity refresh)'
            d=REGISTRY.get(u)
            # Reviewed registry preserves the separate municipal library image source.
            d=_extract(d['source_url'] if d else u,session) or d
            if not d:return u,None
            im=d['original_image_url'];source=d['source_url']
            if not _valid(im,ALLOWED_IMAGES) or PLACEHOLDER.search(urlsplit(im).path):return u,None
            r=session.get(im,headers={'Referer':source},timeout=25);r.raise_for_status()
            if not r.headers.get('Content-Type','').startswith('image/') or len(r.content)<1200:return u,None
            image_url=im
            if asset_dir and asset_url_base:
                from PIL import Image
                pic=Image.open(io.BytesIO(r.content));pic.load()
                if pic.width<200 or pic.height<150:return u,None
                pic=pic.convert('RGB');pic.thumbnail((1400,1400))
                target=Path(asset_dir);target.mkdir(parents=True,exist_ok=True)
                name=hashlib.sha256(u.encode()).hexdigest()[:20]+'.jpg'
                pic.save(target/name,quality=88)
                image_url=asset_url_base.rstrip('/')+'/'+name
            return u,{'image_url':image_url,'image_credit':d['credit'],'image_source_url':source,'image_original_url':im,'image_rights':'user_confirmed_organizer_publicity','image_represents_event':True,'image_verified':True,'image_rights_evidence':'Publisher confirmed permission for producer/PR/municipal publicity. Exact official event or series asset; not a free-license claim.'}
        except (Exception,):return u,None
    mapped={}
    with ThreadPoolExecutor(max_workers=5) as pool:
        for u,d in pool.map(one,by.items()):
            if d:mapped[u]=d
    return [{**e,**mapped.get(e.get('source_url'),{})} for e in events]
